/* ================= CFA Level I: missions (original content aligned to CFA Institute's topic outline) ================= */
const CFAI='https://www.cfainstitute.org/programs/cfa-program';
const CFAS='https://www.cfainstitute.org/standards/professionals/code-ethics-standards';
Object.assign(MICON,{a01:'shield',a02:'shield',a03:'scale',a04:'clock',a05:'scatter',a06:'landmark',a07:'globe',a08:'doc',a09:'cycle',a10:'boxes',a11:'alert',a12:'users',a13:'barchart',a14:'trend',a15:'percent',a16:'curve',a17:'layers',a18:'split',a19:'grid',a20:'pie'});
addMissions([
{id:'a01',track:'cfa1',topic:'eth',title:'Ethics: Code and Standards I–III',mins:45,blurb:'The Code of Ethics and Standards I to III: professionalism, market integrity and duties to clients.',
 lab:{key:'ethstd',name:'Which standard applies?',intro:'Eight original scenarios. Name the standard most directly involved.'},
 cards:[
  {h:'The Code of Ethics',b:`<p>Members and candidates must act with integrity, competence, diligence and respect; put clients' interests and the integrity of the profession above their own; use reasonable care and independent judgement; practise in a professional manner; promote the integrity of capital markets; and maintain and develop their competence.</p>`},
  {h:'Standard I: Professionalism',b:`<ul><li><b>I(A) Knowledge of the Law:</b> follow the stricter of the law or the Code and Standards; dissociate from violations.</li><li><b>I(B) Independence and Objectivity:</b> no gifts or pressure that compromise judgement (modest gifts fine; disclose client gifts to employer).</li><li><b>I(C) Misrepresentation:</b> no false statements, no plagiarism.</li><li><b>I(D) Misconduct:</b> no dishonesty, fraud or deceit.</li><li><b>I(E) Competence:</b> act with and maintain the competence your responsibilities require (added effective 2024).</li></ul>`},
  {h:'Standard II: Integrity of Capital Markets',b:`<p><b>II(A) Material Nonpublic Information:</b> do not act or cause others to act on it. The <b>mosaic theory</b> allows conclusions from public information plus non-material nonpublic information.</p><p><b>II(B) Market Manipulation:</b> no transactions or information that distort prices or volume to mislead.</p>`},
  {h:'Standard III: Duties to Clients',b:`<ul><li><b>III(A) Loyalty, Prudence and Care:</b> clients first; for pooled funds the duty is to the mandate.</li><li><b>III(B) Fair Dealing:</b> fair, not necessarily equal, treatment in recommendations and actions.</li><li><b>III(C) Suitability:</b> know the client, document an IPS, review it.</li><li><b>III(D) Performance Presentation:</b> fair, accurate, complete.</li><li><b>III(E) Preservation of Confidentiality.</b></li></ul>`},
  {h:'How ethics is examined',b:`<p>Questions are short scenarios: decide whether a standard is violated, which one, and the correct action. Typical traps: "the law allows it" (apply the stricter rule), "everyone at my firm does it", and partial disclosure.</p>`}],
 quiz:[
  {q:'Local law permits an action that the Standards prohibit. A member should:',o:['Follow local law','Follow the Code and Standards, as the stricter requirement','Ask the client to decide'],a:1,w:'Apply the stricter of applicable law and the Code and Standards (I(A)).'},
  {q:'Under the mosaic theory, an analyst may reach a conclusion using:',o:['Material nonpublic information if it is combined with public data','Public information and non-material nonpublic information','Any information obtained legally'],a:1,w:'Material nonpublic information may never be used, even as one piece.'},
  {q:'An analyst receives an expensive watch from a company she covers. The standard most at risk is:',o:['I(B) Independence and Objectivity','III(B) Fair Dealing','IV(A) Loyalty'],a:0,w:'Gifts from issuers can compromise objectivity.'},
  {q:'Fair dealing requires that clients be treated:',o:['Equally in all respects','Fairly, so no client is disadvantaged; different service levels are allowed if disclosed','According to account size'],a:1,w:'Fair, not identical; premium services are permitted when disclosed and available to all who pay.'},
  {q:'Which action satisfies III(C) Suitability for an individual client?',o:['Selling the firm\'s best-performing fund','Documenting objectives and constraints in an IPS and reviewing it regularly','Asking the client to sign a risk waiver'],a:1,w:'Know the client and keep the IPS current.'},
  {q:'Copying another analyst\'s research without attribution violates:',o:['I(C) Misrepresentation','II(B) Market Manipulation','V(C) Record Retention'],a:0,w:'Plagiarism is misrepresentation.'},
  {q:'Spreading false positive rumours about a stock before selling it is:',o:['Permitted if the analyst holds no position','Market manipulation under II(B)','Only a firm-policy matter'],a:1,w:'Information-based manipulation.'},
  {q:'The Competence standard I(E) became effective in:',o:['2014','2024','It does not exist'],a:1,w:'Added in the 2023 revisions, effective 1 January 2024.'},
  {q:'When managing a fund to a stated mandate, the duty of loyalty is owed primarily to:',o:['Each individual investor\'s personal needs','The fund\'s stated mandate and its investors as a group','The employer'],a:1,w:'For pooled vehicles, follow the mandate.'},
  {q:'A member discovers her employer is breaking the law. Under I(A), the minimum action is to:',o:['Report to regulators immediately in all cases','Dissociate from the activity, often by raising it with compliance and, if needed, resigning','Ignore it if she is not involved'],a:1,w:'Dissociation is required; reporting to authorities may be advisable or required by law.'}],
 srs:[{q:'Seven Standards headings?',a:'I Professionalism, II Integrity of Capital Markets, III Duties to Clients, IV Duties to Employers, V Investment Analysis/Recommendations/Actions, VI Conflicts of Interest, VII Responsibilities as Member/Candidate.'},{q:'Mosaic theory?',a:'Public + non-material nonpublic information may be combined; material nonpublic may not be used.'},{q:'Standard I sub-standards?',a:'(A) Knowledge of the Law, (B) Independence and Objectivity, (C) Misrepresentation, (D) Misconduct, (E) Competence.'},{q:'Stricter rule?',a:'Follow the stricter of law and the Code and Standards.'}],
 read:[{t:'Code of Ethics and Standards of Professional Conduct',s:'CFA Institute',u:CFAS},{t:'CFA Program overview and curriculum access',s:'CFA Institute',u:CFAI},{t:'Summary of the 2023 revisions to the Code and Standards',s:'CFA Institute (PDF)',u:'https://www.cfainstitute.org/-/media/documents/support/ethics/summary-of-the-2023-revisions-to-the-cfa-institute-code-and-standards.pdf'}]},

{id:'a02',track:'cfa1',topic:'eth',title:'Ethics: Standards IV–VII and GIPS',mins:45,blurb:'Duties to employers, investment analysis, conflicts, CFA responsibilities, and the GIPS standards.',
 lab:{key:'ethstd',name:'Which standard applies?',intro:'Nine more original scenarios covering Standards IV to VII.'},
 cards:[
  {h:'Standard IV: Duties to Employers',b:`<ul><li><b>IV(A) Loyalty:</b> act for the employer's benefit; preparing to compete is allowed, misappropriating clients or records is not.</li><li><b>IV(B) Additional Compensation Arrangements:</b> get written consent from all parties before accepting outside compensation that conflicts.</li><li><b>IV(C) Responsibilities of Supervisors:</b> make reasonable efforts to ensure compliance by those you supervise.</li></ul>`},
  {h:'Standard V: Investment Analysis, Recommendations and Actions',b:`<ul><li><b>V(A) Diligence and Reasonable Basis.</b></li><li><b>V(B) Communication with Clients:</b> disclose the investment process, significant limitations and risks, and (since 2024) the nature of services and their costs; distinguish fact from opinion.</li><li><b>V(C) Record Retention:</b> keep records supporting analysis (seven years is the guidance absent other rules).</li></ul>`},
  {h:'Standard VI: Conflicts of Interest',b:`<ul><li><b>VI(A) Avoid or Disclose Conflicts</b> (renamed in 2024, now emphasising avoidance first).</li><li><b>VI(B) Priority of Transactions:</b> clients and employer before personal trades.</li><li><b>VI(C) Referral Fees:</b> disclose to employer, clients and prospects.</li></ul>`},
  {h:'Standard VII: Responsibilities as Member or Candidate',b:`<p><b>VII(A)</b> no conduct that compromises the reputation or integrity of CFA Institute, the designation or exams (no sharing exam content). <b>VII(B)</b> no misrepresenting the designation: no "partial" CFA, no "expected" charter; you may state you passed levels.</p>`},
  {h:'GIPS standards',b:`<p>The Global Investment Performance Standards are voluntary, ethical standards for presenting investment performance fairly and with full disclosure. Firms claim compliance firm-wide; they present composites of all fee-paying discretionary portfolios with similar strategies. Verification by a third party is recommended, not required.</p>`}],
 quiz:[
  {q:'An employee may, before leaving, do which of the following without violating IV(A)?',o:['Take client contact lists for later use','Make preparations such as registering a new company, on her own time','Solicit current clients while still employed'],a:1,w:'Preparation is allowed; misappropriation and solicitation are not.'},
  {q:'Additional compensation that could conflict with the employer requires:',o:['Oral notice to a colleague','Written consent from all parties involved','No action if under USD 1,000'],a:1,w:'IV(B).'},
  {q:'A supervisor who learns of a possible violation should first:',o:['Wait for compliance to notice','Promptly investigate and take steps to prevent recurrence','Report to the press'],a:1,w:'IV(C) reasonable efforts.'},
  {q:'The 2024 revision to V(B) added a requirement to disclose:',o:['The analyst\'s salary','The nature of services provided and their costs to the client','All proprietary models'],a:1,w:'Disclosure of services and associated costs.'},
  {q:'Absent regulatory guidance, CFA Institute recommends retaining records for at least:',o:['3 years','7 years','20 years'],a:1,w:'Seven years.'},
  {q:'A portfolio manager trades for himself before a client block order. This violates:',o:['VI(B) Priority of Transactions','III(D) Performance Presentation','VII(A)'],a:0,w:'Clients and employer come first.'},
  {q:'Which statement about the designation is permitted?',o:['"John Smith, CFA Level III"','"I passed Level II of the CFA Program on my first attempt"','"CFA (expected 2027)"'],a:1,w:'Factual statements about passed levels are allowed.'},
  {q:'GIPS compliance is claimed:',o:['Per product','On a firm-wide basis','Only after verification'],a:1,w:'Firm-wide.'},
  {q:'A GIPS composite includes:',o:['Only the best-performing accounts','All actual fee-paying discretionary portfolios managed to a similar strategy','Model portfolios'],a:1,w:'No cherry-picking.'},
  {q:'Third-party verification under GIPS is:',o:['Required','Recommended but voluntary','Prohibited'],a:1,w:'Recommended.'}],
 srs:[{q:'Standard IV sub-standards?',a:'(A) Loyalty, (B) Additional Compensation Arrangements, (C) Responsibilities of Supervisors.'},{q:'Standard VI sub-standards?',a:'(A) Avoid or Disclose Conflicts, (B) Priority of Transactions, (C) Referral Fees.'},{q:'V(B) 2024 addition?',a:'Disclose nature of services and their costs to the client.'},{q:'GIPS basics?',a:'Voluntary, firm-wide claim; composites of all fee-paying discretionary portfolios; verification recommended.'}],
 read:[{t:'Code of Ethics and Standards of Professional Conduct',s:'CFA Institute',u:CFAS},{t:'GIPS standards',s:'CFA Institute',u:'https://www.gipsstandards.org/'},{t:'Standards of Practice Handbook (12th edition)',s:'CFA Institute (PDF)',u:'https://www.cfainstitute.org/-/media/documents/code/code-ethics-standards/standards-practice-handbook-12th-edition.pdf'}]},

{id:'a03',track:'cfa1',topic:'eth',title:'Ethics case drill',mins:35,blurb:'Practise the judgement calls that decide ethics questions.',
 lab:{key:'ethcase',name:'Violation or not?',intro:'Nine scenarios. Decide, then read the reason.'},
 cards:[
  {h:'A decision routine',b:`<ol><li>Who is the member, and in what role?</li><li>What duty applies (client, employer, market, profession)?</li><li>Is there a conflict, a misstatement, or information misuse?</li><li>Was it disclosed, consented to or documented?</li><li>What is the required or recommended action?</li></ol>`},
  {h:'Disclosure often cures',b:`<p>Many conflicts (referral fees, holdings, outside work) are acceptable when properly disclosed or consented to. Disclosure does <b>not</b> cure misuse of material nonpublic information, misrepresentation or manipulation.</p>`},
  {h:'Recommended procedures',b:`<p>The Standards include recommended procedures for compliance: written policies, blackout periods, restricted lists, information barriers ("firewalls"), and pre-clearance of personal trades. Exams test which procedure best addresses a situation.</p>`},
  {h:'Common traps',b:`<ul><li>"It was legal" — the stricter rule still applies.</li><li>"The client agreed" — clients cannot waive suitability or fair dealing for others.</li><li>"Small gift" — fine from clients if disclosed; risky from issuers.</li></ul>`},
  {h:'Weight matters',b:`<p>Ethics is 15–20% of Level I and is studied by many candidates last; it repays early, regular practice. Re-read the Standards' text itself, not only summaries.</p>`}],
 quiz:[
  {q:'An analyst learns of an unannounced merger from a friend at the target company. She should:',o:['Trade but not tell clients','Not trade or cause others to trade, and encourage public dissemination where appropriate','Trade only if she believes the information is already rumoured'],a:1,w:'II(A).'},
  {q:'Information barriers (firewalls) primarily help prevent:',o:['Misuse of material nonpublic information','Poor performance','High fees'],a:0,w:'Separating research from investment banking.'},
  {q:'A client asks to be excluded from an IPO allocation so others get more. The manager:',o:['Must refuse','May honour the client\'s documented instruction','Must allocate pro rata anyway'],a:1,w:'Clients can decline; fair dealing concerns are about the firm\'s choices.'},
  {q:'A referral fee arrangement is acceptable if:',o:['It is under 1% of assets','It is disclosed to the employer, clients and prospects before engagement','The broker is reputable'],a:1,w:'VI(C).'},
  {q:'A member gives an opinion as if it were a certain fact. This violates:',o:['V(B)','IV(C)','II(B)'],a:0,w:'Distinguish fact from opinion.'},
  {q:'Personal trading pre-clearance is a recommended procedure mainly for:',o:['VI(B) Priority of Transactions','III(E) Confidentiality','VII(B)'],a:0,w:'Prevents front-running.'},
  {q:'A candidate discusses broad topic areas of the exam after sitting it. This is:',o:['A violation','Not a violation if no specific questions or answers are disclosed','A violation only for Level III'],a:1,w:'Broad topics are fine; specific content is not.'},
  {q:'Using a client\'s confidential information to defend against a legal claim by the client is:',o:['A violation','Permitted','Permitted only with CFA Institute approval'],a:1,w:'Confidentiality exceptions include legal requirements and the member\'s defence.'},
  {q:'Which does disclosure NOT cure?',o:['Holding shares in a covered company','Acting on material nonpublic information','Receiving a referral fee'],a:1,w:'MNPI misuse is never acceptable.'},
  {q:'A manager deviates from a client\'s IPS to chase returns without consulting the client. Most directly:',o:['III(C) Suitability','IV(B)','VII(A)'],a:0,w:'Actions must fit the client\'s IPS.'}],
 srs:[{q:'What can disclosure cure?',a:'Conflicts like holdings, referral fees, outside work — not MNPI misuse, misrepresentation or manipulation.'},{q:'Firewalls address?',a:'Flow of material nonpublic information between departments.'},{q:'Pre-clearance addresses?',a:'Priority of transactions (front-running).'},{q:'Five-step ethics routine?',a:'Role → duty → conflict/misstatement/info → disclosure/consent → required action.'}],
 read:[{t:'Ethics in Practice resources',s:'CFA Institute',u:'https://www.cfainstitute.org/standards/professionals/code-ethics-standards'},{t:'Standards of Practice Handbook',s:'CFA Institute (PDF)',u:'https://www.cfainstitute.org/-/media/documents/code/code-ethics-standards/standards-practice-handbook-12th-edition.pdf'},{t:'CFA Program',s:'CFA Institute',u:CFAI}]},

{id:'a04',track:'cfa1',topic:'qm',title:'Rates, returns and time value of money',mins:40,blurb:'Interest rates, return measures, compounding and annuities.',
 lab:{key:'tvm',name:'TVM calculator',intro:'PV, FV, annuities and effective annual rates.'},
 cards:[
  {h:'Interest rate components',b:`<div class="formula">r ≈ real risk-free rate + expected inflation + default risk + liquidity + maturity premiums</div>`},
  {h:'Compounding',b:`<div class="formula">FV = PV(1 + r/m)^(mN) · EAR = (1 + APR/m)^m − 1 · Continuous: FV = PV·e^(rN)</div>`},
  {h:'Annuities and perpetuities',b:`<div class="formula">PV(ordinary annuity) = A[1 − (1 + r)^−N] ÷ r · PV(perpetuity) = A ÷ r · Annuity due = ordinary × (1 + r)</div>`},
  {h:'Return measures',b:`<ul><li>Holding period return = (P₁ − P₀ + D) ÷ P₀</li><li>Arithmetic mean ≥ geometric mean ≥ harmonic mean</li><li>Money-weighted return = IRR of investor cash flows; time-weighted return removes the effect of flows (used for manager evaluation)</li><li>Annualised: (1 + r_period)^(periods per year) − 1</li></ul>`},
  {h:'Calculator discipline',b:`<p>Set P/Y = 1, use periodic rates, and keep sign conventions consistent (outflows negative). Most TVM errors on exam day are keystrokes, not concepts.</p>`}],
 quiz:[
  {q:'APR 12% compounded monthly. EAR is closest to:',o:['12.00%','12.68%','12.36%'],a:1,w:'1.01¹² − 1 = 12.68%.'},
  {q:'PV of a perpetuity paying 50 a year at 8%:',o:['400','625','4,000'],a:1,w:'50 ÷ 0.08.'},
  {q:'An annuity due is worth more than an ordinary annuity because:',o:['Payments are larger','Each payment arrives one period earlier','It has more payments'],a:1,w:'Multiply by (1 + r).'},
  {q:'Returns of +50% and −50%. Geometric mean return:',o:['0%','about −13.4%','−25%'],a:1,w:'√(1.5 × 0.5) − 1 = −13.4%.'},
  {q:'To evaluate a manager who does not control client cash flows, use:',o:['Money-weighted return','Time-weighted return','Arithmetic mean only'],a:1,w:'TWR removes flow timing effects.'},
  {q:'FV of 1,000 after 3 years at 5% compounded annually:',o:['1,150.00','1,157.63','1,161.83'],a:1,w:'1.05³ × 1,000.'},
  {q:'Which premium compensates for the risk of selling quickly at a fair price?',o:['Maturity premium','Liquidity premium','Default premium'],a:1,w:'Liquidity.'},
  {q:'A 2% monthly return annualises to:',o:['24.00%','26.82%','25.34%'],a:1,w:'1.02¹² − 1.'},
  {q:'Continuous compounding at 6% for 2 years turns 100 into:',o:['112.36','112.75','112.00'],a:1,w:'100e^0.12.'},
  {q:'Harmonic mean is most associated with:',o:['Cost averaging (buying a fixed amount at varying prices)','Bond duration','Portfolio variance'],a:0,w:'Average price paid in cost averaging.'}],
 srs:[{q:'EAR?',a:'(1 + APR/m)^m − 1.'},{q:'PV of perpetuity?',a:'A ÷ r.'},{q:'TWR vs MWR?',a:'TWR removes cash-flow timing (manager evaluation); MWR = IRR (investor experience).'},{q:'Mean ordering?',a:'Arithmetic ≥ geometric ≥ harmonic.'}],
 read:[{t:'Time value of money',s:'Investopedia',u:INV('t/timevalueofmoney.asp')},{t:'Time-weighted vs money-weighted return',s:'Investopedia',u:INV('t/time-weightedror.asp')},{t:'CFA Program curriculum (Quantitative Methods)',s:'CFA Institute',u:CFAI}]},

{id:'a05',track:'cfa1',topic:'qm',title:'Statistics, hypothesis tests and regression',mins:45,blurb:'Distributions, sampling, hypothesis testing and simple linear regression.',
 lab:{key:'ttest',name:'Hypothesis test of a mean',intro:'Compute t, compare with the critical value, decide.'},
 cards:[
  {h:'Describing data',b:`<p>Central tendency (mean, median, mode), dispersion (range, variance, standard deviation, coefficient of variation = σ ÷ mean), shape (skewness, kurtosis). Positive skew: mean > median > mode. Fat tails = excess kurtosis > 0.</p>`},
  {h:'Probability tools',b:`<div class="formula">E(X) = Σ p·x · Var(aX + bY) = a²σ²_X + b²σ²_Y + 2ab·Cov(X, Y) · Bayes: P(A|B) = P(B|A)P(A) ÷ P(B)</div>`},
  {h:'Normal distribution',b:`<p>~68% within ±1σ, ~95% within ±1.96σ, ~99% within ±2.58σ. Standardise with z = (x − μ) ÷ σ. Lognormal is used for prices (cannot go below zero).</p>`},
  {h:'Hypothesis testing',b:`<ol><li>State H₀ and Hₐ</li><li>Choose the test statistic (z, t, χ², F)</li><li>Set α (Type I error)</li><li>Decision rule (critical value or p-value)</li><li>Decide and interpret</li></ol><p>Power = 1 − P(Type II error).</p>`},
  {h:'Simple linear regression',b:`<div class="formula">Y = b₀ + b₁X + ε · b₁ = Cov(X, Y) ÷ Var(X) · R² = explained ÷ total variation</div><p>Assumptions: linearity, homoskedasticity, independent and normal residuals. Test slope with t = b̂₁ ÷ s(b̂₁).</p>`}],
 quiz:[
  {q:'Positively skewed distribution: which is typically true?',o:['Mean < median','Mean > median > mode','Mode > mean'],a:1,w:'Tail to the right pulls the mean up.'},
  {q:'Rejecting a true null hypothesis is a:',o:['Type I error','Type II error','Power failure'],a:0,w:'Probability = α.'},
  {q:'Sample mean 1.4, H₀ mean 0, s 4.2, n 36. t-statistic:',o:['0.33','2.00','1.40'],a:1,w:'1.4 ÷ (4.2 ÷ 6) = 2.0.'},
  {q:'With n = 36, degrees of freedom for a t-test of the mean:',o:['36','35','34'],a:1,w:'n − 1.'},
  {q:'Coefficient of variation is useful to compare:',o:['Risk per unit of return across assets','Skewness','Correlation'],a:0,w:'CV = σ ÷ mean.'},
  {q:'About what share of a normal distribution lies within ±1.96σ?',o:['68%','95%','99%'],a:1,w:'Two-tailed 5%.'},
  {q:'Slope b₁ in simple regression equals:',o:['Cov(X,Y) ÷ Var(X)','Cov(X,Y) ÷ Var(Y)','Corr(X,Y)'],a:0,w:'OLS slope.'},
  {q:'Variance of residuals that changes with X indicates:',o:['Multicollinearity','Heteroskedasticity','Normality'],a:1,w:'Violates homoskedasticity.'},
  {q:'Increasing α from 1% to 5% (other things equal):',o:['Raises the chance of a Type I error and raises power','Lowers both','Has no effect'],a:0,w:'Trade-off between Type I and Type II.'},
  {q:'Excess kurtosis > 0 means:',o:['Thinner tails than normal','Fatter tails than normal','No skew'],a:1,w:'Leptokurtic.'}],
 srs:[{q:'Type I vs Type II?',a:'Type I: reject true H₀ (α). Type II: fail to reject false H₀ (β). Power = 1 − β.'},{q:'t-stat for mean?',a:'(x̄ − μ₀) ÷ (s ÷ √n), df = n − 1.'},{q:'OLS slope?',a:'Cov(X,Y) ÷ Var(X).'},{q:'Normal coverage?',a:'±1σ 68%, ±1.96σ 95%, ±2.58σ 99%.'}],
 read:[{t:'Hypothesis testing',s:'Investopedia',u:INV('h/hypothesistesting.asp')},{t:'NIST e-Handbook of Statistical Methods',s:'NIST',u:'https://www.itl.nist.gov/div898/handbook/'},{t:'A Refresher on Regression Analysis',s:'Harvard Business Review',u:'https://hbr.org/2015/11/a-refresher-on-regression-analysis'}]},

{id:'a06',track:'cfa1',topic:'eco',title:'Markets, business cycles and policy',mins:40,blurb:'Market structures, the business cycle, and fiscal and monetary policy.',
 lab:{key:'taylor',name:'Taylor rule and policy stance',intro:'Compute a rule-based policy rate and judge the stance.'},
 cards:[
  {h:'Market structures',b:`<p>Perfect competition (price = MC, no long-run economic profit) · monopolistic competition (differentiation) · oligopoly (interdependence: Cournot, Stackelberg, kinked demand) · monopoly (MR = MC, price above MC). Concentration measures: N-firm ratio, Herfindahl-Hirschman Index.</p>`},
  {h:'Business cycle',b:`<p>Phases: recovery → expansion → slowdown → contraction. Leading indicators (new orders, building permits, yield curve) turn before the economy; coincident and lagging follow. Inventory and capex swings drive much of the cycle.</p>`},
  {h:'Monetary policy',b:`<p>Tools: policy rate, open-market operations, reserve requirements. Transmission: rates → asset prices → expectations → exchange rate → spending. Policy is expansionary when the policy rate is below the neutral rate. Limits: liquidity traps, deflation, credibility.</p>`},
  {h:'Fiscal policy',b:`<p>Government spending and taxes. Fiscal multiplier = 1 ÷ [1 − c(1 − t)]. Automatic stabilisers (progressive taxes, transfers) vs discretionary policy. Lags: recognition, action, impact. Crowding out when deficits raise rates.</p>`},
  {h:'Policy mix',b:`<p>Loose fiscal + tight monetary → higher rates, larger public sector share. Tight fiscal + loose monetary → lower rates, private sector grows. Pegged currencies (like the riyal) import monetary policy, leaving fiscal policy as the main tool.</p>`}],
 quiz:[
  {q:'A firm in perfect competition in the long run earns:',o:['Positive economic profit','Zero economic profit','Losses'],a:1,w:'Entry drives profit to zero.'},
  {q:'Monopolists maximise profit where:',o:['P = MC','MR = MC','P = ATC'],a:1,w:'Then price from demand.'},
  {q:'Which is a leading indicator?',o:['Unemployment rate','Building permits','Average duration of unemployment'],a:1,w:'Turns before activity.'},
  {q:'Marginal propensity to consume 0.8, tax rate 25%. Fiscal multiplier:',o:['2.5','5.0','1.67'],a:0,w:'1 ÷ [1 − 0.8 × 0.75] = 2.5.'},
  {q:'Policy rate below the neutral rate means policy is:',o:['Contractionary','Expansionary','Neutral'],a:1,w:'Stimulative.'},
  {q:'Taylor rule with neutral real 1%, inflation 4%, target 2%, output gap −1%:',o:['5.5%','6.0%','4.5%'],a:0,w:'1 + 4 + 1 − 0.5 = 5.5.'},
  {q:'Crowding out occurs when:',o:['Government borrowing raises rates and reduces private investment','Taxes fall','Exports rise'],a:0,w:'Competition for funds.'},
  {q:'A high Herfindahl-Hirschman Index indicates:',o:['Many small firms','High concentration','Perfect competition'],a:1,w:'Sum of squared market shares.'},
  {q:'With a currency peg to the dollar, domestic interest rates are mainly set by:',o:['Domestic inflation targeting','The anchor currency\'s policy rates','Fiscal policy'],a:1,w:'To defend the peg.'},
  {q:'Kinked demand curve model explains:',o:['Price stickiness in oligopoly','Monopoly pricing','Perfect competition'],a:0,w:'Rivals match cuts but not increases.'}],
 srs:[{q:'Fiscal multiplier?',a:'1 ÷ [1 − c(1 − t)].'},{q:'Taylor rule?',a:'i = r_n + π + 0.5(π − π*) + 0.5(output gap).'},{q:'Expansionary monetary stance?',a:'Policy rate below neutral rate.'},{q:'Four market structures?',a:'Perfect competition, monopolistic competition, oligopoly, monopoly.'}],
 read:[{t:'IMF: Saudi Arabia',s:'International Monetary Fund',u:'https://www.imf.org/en/Countries/SAU'},{t:'Taylor rule',s:'Wikipedia',u:WIKI('Taylor_rule')},{t:'Herfindahl–Hirschman index',s:'Wikipedia',u:WIKI('Herfindahl%E2%80%93Hirschman_index')}]},

{id:'a07',track:'cfa1',topic:'eco',title:'International trade and exchange rates',mins:40,blurb:'Trade, balance of payments, exchange-rate regimes, cross rates and forwards.',
 lab:{key:'fxfwd',name:'Forward and cross-rate calculator',intro:'Covered interest parity in practice, with SAR, USD and EUR.'},
 cards:[
  {h:'Gains from trade',b:`<p>Comparative advantage (lower opportunity cost) drives trade. Restrictions: tariffs, quotas, export subsidies, voluntary export restraints — each creates deadweight losses for the importing country overall.</p>`},
  {h:'Balance of payments',b:`<p>Current account (goods, services, income, transfers) + capital account + financial account = 0 (with errors). A current-account deficit must be financed by financial inflows.</p><div class="formula">CA = (S − I) + (T − G)</div>`},
  {h:'Quotes and cross rates',b:`<p>Quote "price/base": SAR/USD 3.75 means 3.75 SAR per USD. Cross rate: EUR/SAR = EUR/USD × USD/SAR, with care over which currency is base.</p>`},
  {h:'Forwards',b:`<div class="formula">F(p/b) = S(p/b) × (1 + i_p·t) ÷ (1 + i_b·t)</div><p>Higher-interest currency trades at a forward discount. Forward points = (F − S) × scale.</p>`},
  {h:'Regimes',b:`<p>From hard pegs (currency board, dollarisation) through conventional pegs (the riyal at 3.75 per USD since 1986), crawling pegs and managed floats to independent floats. Pegs import the anchor's monetary policy.</p>`}],
 quiz:[
  {q:'SAR/USD spot 3.75, SAR rate 5.5%, USD rate 5.0%, 180 days (360-day year). Forward is closest to:',o:['3.7591','3.7409','3.7500'],a:0,w:'3.75 × 1.0275 ÷ 1.025 ≈ 3.7591.'},
  {q:'The currency with the higher interest rate trades at a forward:',o:['Premium','Discount','Par'],a:1,w:'Covered interest parity.'},
  {q:'A country with a current-account deficit must have:',o:['A financial-account surplus (net inflows)','A budget surplus','A floating currency'],a:0,w:'BOP identity.'},
  {q:'A tariff on imports typically:',o:['Benefits domestic consumers','Benefits domestic producers and government, with an overall deadweight loss','Has no effect on prices'],a:1,w:'Classic trade analysis.'},
  {q:'USD per EUR 1.08 and SAR per USD 3.75. SAR per EUR:',o:['4.05','3.47','2.67'],a:0,w:'1.08 × 3.75.'},
  {q:'Comparative advantage depends on:',o:['Absolute productivity','Opportunity cost','Exchange rate only'],a:1,w:'Ricardo.'},
  {q:'The Saudi riyal regime is best described as:',o:['Independent float','Conventional fixed peg to the US dollar','Currency board with the euro'],a:1,w:'Pegged at 3.75 since 1986.'},
  {q:'CA = (S − I) + (T − G). A larger fiscal deficit, other things equal, tends to:',o:['Increase the current-account balance','Reduce the current-account balance','Not affect it'],a:1,w:'Twin-deficits logic.'},
  {q:'If the base currency appreciates, the quote (price/base):',o:['Falls','Rises','Stays the same'],a:1,w:'More price currency per base unit.'},
  {q:'Forward rates are best described as:',o:['Unbiased forecasts of future spot','No-arbitrage prices reflecting interest differentials','Central bank targets'],a:1,w:'Not forecasts.'}],
 srs:[{q:'Forward formula?',a:'F = S × (1 + i_price·t) ÷ (1 + i_base·t).'},{q:'BOP identity link?',a:'CA = (S − I) + (T − G); CA deficit financed by financial inflows.'},{q:'Higher-rate currency forward?',a:'Trades at a forward discount.'},{q:'Riyal regime?',a:'Conventional peg, 3.75 SAR per USD since 1986.'}],
 read:[{t:'Saudi Central Bank (SAMA)',s:'SAMA',u:'https://www.sama.gov.sa/'},{t:'Interest rate parity',s:'Investopedia',u:INV('i/interestrateparity.asp')},{t:'Balance of payments',s:'Wikipedia',u:WIKI('Balance_of_payments')}]},

{id:'a08',track:'cfa1',topic:'fsa',title:'Income statement and balance sheet',mins:45,blurb:'Revenue recognition, expenses, EPS, and balance-sheet classification under IFRS and US GAAP.',
 lab:{key:'ratios',name:'Ratio calculator',intro:'Build the key ratios from a simple set of statements.'},
 cards:[
  {h:'Revenue recognition',b:`<p>IFRS 15 / ASC 606 five steps: identify the contract → identify performance obligations → determine price → allocate price → recognise revenue when (or as) obligations are satisfied.</p>`},
  {h:'Expenses and EPS',b:`<div class="formula">Basic EPS = (NI − preferred dividends) ÷ weighted average shares · Diluted EPS adds potentially dilutive securities (if-converted, treasury stock methods)</div><p>Antidilutive securities are excluded.</p>`},
  {h:'Balance sheet',b:`<p>Current vs non-current classification; measurement bases (historical cost, amortised cost, fair value). Equity includes contributed capital, retained earnings, treasury shares, and accumulated other comprehensive income.</p>`},
  {h:'Other comprehensive income',b:`<p>Items bypassing profit or loss: some fair-value changes, translation adjustments, certain pension remeasurements, cash-flow hedge effects. Comprehensive income = NI + OCI.</p>`},
  {h:'Common-size analysis',b:`<p>Express the income statement as % of revenue and the balance sheet as % of total assets to compare companies of different size and spot trends.</p>`}],
 quiz:[
  {q:'Under IFRS 15, revenue is recognised when:',o:['Cash is received','Performance obligations are satisfied','The contract is signed'],a:1,w:'Transfer of control.'},
  {q:'Basic EPS: NI 500, preferred dividends 50, weighted shares 150:',o:['3.33','3.00','3.67'],a:1,w:'450 ÷ 150.'},
  {q:'A convertible whose conversion would raise diluted EPS is:',o:['Included','Antidilutive and excluded','Counted twice'],a:1,w:'Exclude antidilutive securities.'},
  {q:'Which flows through other comprehensive income?',o:['Foreign currency translation adjustments','Cost of goods sold','Interest expense'],a:0,w:'Classic OCI item.'},
  {q:'Comprehensive income equals:',o:['Net income','Net income + OCI','Revenue − expenses'],a:1,w:'Definition.'},
  {q:'Treasury shares appear:',o:['As an asset','As a reduction of equity','As a liability'],a:1,w:'Contra-equity.'},
  {q:'A common-size income statement expresses items as a percentage of:',o:['Total assets','Revenue','Net income'],a:1,w:'Vertical analysis.'},
  {q:'The treasury stock method applies to:',o:['Convertible bonds','Options and warrants','Preferred stock'],a:1,w:'Assumed exercise proceeds buy back shares.'},
  {q:'Current ratio 1.6 with current liabilities 250 implies current assets of:',o:['400','156','640'],a:0,w:'1.6 × 250.'},
  {q:'Revenue from a 3-year software support contract paid upfront is recognised:',o:['All at signing','Over the service period','At the end'],a:1,w:'Over time as obligation is satisfied.'}],
 srs:[{q:'IFRS 15 five steps?',a:'Contract, performance obligations, price, allocation, recognise when satisfied.'},{q:'Basic EPS?',a:'(NI − preferred dividends) ÷ weighted average shares.'},{q:'Diluted EPS methods?',a:'If-converted (convertibles), treasury stock (options/warrants); exclude antidilutive.'},{q:'Comprehensive income?',a:'NI + OCI.'}],
 read:[{t:'IFRS 15 Revenue from Contracts with Customers',s:'IFRS Foundation',u:'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-15-revenue-from-contracts-with-customers/'},{t:'Earnings per share',s:'Investopedia',u:INV('e/eps.asp')},{t:'Financial statements',s:'Investopedia',u:INV('f/financial-statements.asp')}]},

{id:'a09',track:'cfa1',topic:'fsa',title:'Cash flows and analysis tools',mins:40,blurb:'The cash flow statement, direct and indirect methods, free cash flow and ratio analysis.',
 lab:{key:'cfo',name:'Indirect-method CFO builder',intro:'Reconcile net income to operating cash flow.'},
 cards:[
  {h:'Three sections',b:`<p>Operating, investing, financing. IFRS lets interest and dividends received be operating or investing, and interest and dividends paid be operating or financing; US GAAP fixes interest paid and received and dividends received in operating, and dividends paid in financing.</p>`},
  {h:'Indirect method',b:`<div class="formula">CFO = NI + non-cash charges − gains + losses − increases in operating assets + increases in operating liabilities</div>`},
  {h:'Free cash flow',b:`<div class="formula">FCFF = CFO + interest × (1 − t) − FCInv · FCFE = CFO − FCInv + net borrowing</div>`},
  {h:'Ratio families',b:`<p>Activity (turnover), liquidity, solvency, profitability, valuation. DuPont: ROE = net margin × asset turnover × leverage (and the five-way version adds tax and interest burdens).</p>`},
  {h:'Cash vs accrual quality',b:`<p>Persistent gaps where net income exceeds CFO, or rising accruals ratios, are warning signs. Look at the sources of cash: operations, asset sales or borrowing?</p>`}],
 quiz:[
  {q:'NI 120, D&A 40, gain on sale 10, receivables +25, inventory −8, payables +12. CFO:',o:['145','165','125'],a:0,w:'120 + 40 − 10 − 25 + 8 + 12 = 145.'},
  {q:'Under US GAAP, dividends paid are classified as:',o:['Operating','Financing','Investing'],a:1,w:'Fixed classification.'},
  {q:'Under IFRS, interest paid may be classified as:',o:['Operating or financing','Investing only','Financing only'],a:0,w:'Choice under IFRS.'},
  {q:'A gain on sale of equipment is subtracted in the indirect method because:',o:['It is non-recurring','The cash proceeds belong in investing activities','It is taxable'],a:1,w:'Avoid double counting.'},
  {q:'An increase in accounts payable:',o:['Reduces CFO','Increases CFO','Does not affect CFO'],a:1,w:'Cash not yet paid.'},
  {q:'FCFE equals:',o:['CFO − FCInv + net borrowing','CFO + interest(1 − t) − FCInv','NI + D&A'],a:0,w:'Cash available to shareholders.'},
  {q:'Five-way DuPont adds:',o:['Tax burden and interest burden','Dividend payout','Cash conversion'],a:0,w:'NI/EBT and EBT/EBIT.'},
  {q:'NI consistently above CFO for several years suggests:',o:['High earnings quality','Possible aggressive accruals','Conservative accounting'],a:1,w:'Watch accruals.'},
  {q:'Buying equipment for cash appears in:',o:['Operating','Investing','Financing'],a:1,w:'Capex.'},
  {q:'Inventory turnover 8× implies days of inventory of about:',o:['46 days','8 days','365 days'],a:0,w:'365 ÷ 8.'}],
 srs:[{q:'Indirect CFO?',a:'NI + non-cash − gains + losses − ↑operating assets + ↑operating liabilities.'},{q:'FCFF?',a:'CFO + interest(1 − t) − FCInv.'},{q:'IFRS vs US GAAP interest paid?',a:'IFRS: operating or financing; US GAAP: operating.'},{q:'Five-way DuPont?',a:'Tax burden × interest burden × EBIT margin × asset turnover × leverage.'}],
 read:[{t:'Cash flow statement',s:'Investopedia',u:INV('c/cashflowstatement.asp')},{t:'IAS 7 Statement of Cash Flows',s:'IFRS Foundation',u:'https://www.ifrs.org/issued-standards/list-of-standards/ias-7-statement-of-cash-flows/'},{t:'DuPont analysis',s:'Investopedia',u:INV('d/dupontanalysis.asp')}]},

{id:'a10',track:'cfa1',topic:'fsa',title:'Inventories, long-lived assets, taxes and liabilities',mins:45,blurb:'Inventory methods, capitalisation, impairment, deferred taxes, leases and bonds payable.',
 lab:{key:'inventory',name:'FIFO, weighted average and LIFO',intro:'Same units, three methods, three different profits.'},
 cards:[
  {h:'Inventory',b:`<p>FIFO, weighted average, specific identification; LIFO allowed only under US GAAP. In rising prices LIFO → higher COGS, lower inventory and taxes. LIFO reserve converts LIFO to FIFO: Inventory_FIFO = Inventory_LIFO + LIFO reserve. Measurement: lower of cost and NRV (IFRS; reversals allowed).</p>`},
  {h:'Long-lived assets',b:`<p>Capitalising costs raises assets and CFO (cost moves to investing) and smooths earnings. Depreciation methods: straight-line, declining balance, units of production. IFRS allows revaluation and impairment reversals; US GAAP generally does not for assets held for use.</p>`},
  {h:'Income taxes',b:`<p>Temporary differences create deferred tax liabilities (tax base < carrying amount of assets, e.g. accelerated tax depreciation) or deferred tax assets (e.g. warranty provisions, loss carryforwards). Permanent differences change the effective tax rate.</p>`},
  {h:'Leases',b:`<p>IFRS 16: lessees put almost all leases on balance sheet (right-of-use asset and lease liability), with depreciation plus interest expense. US GAAP distinguishes finance and operating leases for the lessee's income statement (operating: single straight-line lease cost).</p>`},
  {h:'Bonds payable',b:`<p>Issued at a discount: interest expense (market rate × carrying amount) exceeds coupon; carrying value rises to par. Effective interest method is required under IFRS.</p>`}],
 quiz:[
  {q:'In a period of rising prices, LIFO compared with FIFO gives:',o:['Higher COGS and lower ending inventory','Lower COGS','Higher taxes'],a:0,w:'Latest (higher) costs expensed.'},
  {q:'LIFO inventory 500, LIFO reserve 80. FIFO inventory:',o:['420','580','500'],a:1,w:'Add the reserve.'},
  {q:'Which framework prohibits LIFO?',o:['US GAAP','IFRS','Both'],a:1,w:'IFRS prohibits.'},
  {q:'Capitalising rather than expensing a cost, in the first year:',o:['Raises CFO and net income','Lowers CFO','Lowers total assets'],a:0,w:'Cost moves to investing; expense spread.'},
  {q:'Accelerated tax depreciation with straight-line book depreciation creates a:',o:['Deferred tax asset','Deferred tax liability','Permanent difference'],a:1,w:'Taxes deferred to later.'},
  {q:'Under IFRS 16, a lessee\'s income statement shows:',o:['A single lease expense','Depreciation and interest expense','No expense'],a:1,w:'Right-of-use model.'},
  {q:'A bond issued at a discount: interest expense compared with coupon paid is:',o:['Higher','Lower','Equal'],a:0,w:'Discount amortises.'},
  {q:'Impairment reversals for assets held for use are permitted under:',o:['IFRS','US GAAP','Neither'],a:0,w:'IFRS allows within limits.'},
  {q:'A warranty provision expensed for books but deductible for tax only when paid creates a:',o:['Deferred tax asset','Deferred tax liability','No difference'],a:0,w:'Future deduction.'},
  {q:'Inventory is written down under IFRS to:',o:['Lower of cost and net realisable value','Replacement cost always','Market value only'],a:0,w:'LCNRV.'}],
 srs:[{q:'LIFO reserve conversion?',a:'FIFO inventory = LIFO inventory + LIFO reserve.'},{q:'DTL arises when?',a:'Taxable income < accounting profit now due to temporary differences (e.g., accelerated tax depreciation).'},{q:'IFRS 16 lessee?',a:'Right-of-use asset + lease liability; depreciation + interest.'},{q:'Capitalise vs expense effect?',a:'Capitalising raises assets, CFO and early earnings; lowers CFI.'}],
 read:[{t:'IFRS 16 Leases',s:'IFRS Foundation',u:'https://www.ifrs.org/issued-standards/list-of-standards/ifrs-16-leases/'},{t:'IAS 2 Inventories',s:'IFRS Foundation',u:'https://www.ifrs.org/issued-standards/list-of-standards/ias-2-inventories/'},{t:'Deferred tax liability',s:'Investopedia',u:INV('d/deferredtaxliability.asp')}]},

{id:'a11',track:'cfa1',topic:'fsa',title:'Reporting quality and ratio applications',mins:35,blurb:'Earnings quality, red flags, and using ratios in credit and equity analysis.',
 lab:{key:'quality',name:'Aggressive or conservative?',intro:'Classify eight accounting choices.'},
 cards:[
  {h:'Quality spectrum',b:`<p>From high-quality, decision-useful reporting with sustainable earnings, down through biased choices (aggressive or conservative), to departures from GAAP and outright fiction. Conservative bias is still bias.</p>`},
  {h:'Motivations and conditions',b:`<p>Fraud triangle: motivation (meeting targets, compensation), opportunity (weak controls), rationalisation. Watch for management pressure around covenant tests and equity issuance.</p>`},
  {h:'Red flags',b:`<ul><li>Revenue growing faster than receivables collection (rising DSO)</li><li>NI persistently above CFO</li><li>Frequent "non-recurring" charges</li><li>Changes in estimates (useful lives, allowances)</li><li>Related-party transactions</li></ul>`},
  {h:'Ratios in credit analysis',b:`<p>The four Cs (capacity, collateral, covenants, character); leverage (debt/EBITDA), coverage (EBITDA/interest), liquidity and cash-flow ratios. Ratings agencies adjust for leases and pensions.</p>`},
  {h:'Ratios in equity screening',b:`<p>Screens combine valuation (P/E, P/B), quality (ROE, accruals) and momentum. Beware look-ahead and survivorship bias when backtesting screens.</p>`}],
 quiz:[
  {q:'Lengthening the depreciable life of assets is:',o:['Conservative','Aggressive','Neutral'],a:1,w:'Lower expense now.'},
  {q:'Rising DSO while revenue grows fast may signal:',o:['Better collections','Aggressive revenue recognition','Conservative accounting'],a:1,w:'Possible channel stuffing.'},
  {q:'The three elements of the fraud triangle:',o:['Motivation, opportunity, rationalisation','Revenue, cost, profit','Audit, control, risk'],a:0,w:'Classic framework.'},
  {q:'Over-reserving in good years to release later is:',o:['"Cookie jar" earnings management','Conservative and acceptable','A cash-flow technique'],a:0,w:'Smoothing via reserves.'},
  {q:'Which ratio is most relevant to debt capacity?',o:['Debt/EBITDA','P/E','Dividend yield'],a:0,w:'Leverage.'},
  {q:'Survivorship bias in backtesting arises when:',o:['Delisted companies are excluded from the historical sample','Data are too recent','Ratios are averaged'],a:0,w:'Inflates results.'},
  {q:'Excluding recurring restructuring costs from "adjusted earnings" every year suggests:',o:['High earnings quality','Questionable non-GAAP reporting','Conservatism'],a:1,w:'Recurring is not one-off.'},
  {q:'Conservative accounting choices:',o:['Are always high quality','Are still a form of bias','Raise current earnings'],a:1,w:'Can shift earnings to later.'},
  {q:'In credit analysis, "covenants" refers to:',o:['Terms that protect lenders','Collateral value','Management character'],a:0,w:'One of the four Cs.'},
  {q:'Accruals much larger than peers\' typically indicate:',o:['Higher earnings quality','Lower earnings quality','No signal'],a:1,w:'Accrual-heavy earnings persist less.'}],
 srs:[{q:'Fraud triangle?',a:'Motivation, opportunity, rationalisation.'},{q:'Four Cs of credit?',a:'Capacity, collateral, covenants, character.'},{q:'Three red flags?',a:'NI > CFO persistently, rising DSO, frequent non-recurring charges (also estimate changes, related parties).'},{q:'Is conservatism high quality?',a:'No: it is still biased reporting.'}],
 read:[{t:'Quality of earnings',s:'Investopedia',u:INV('q/qualityofearnings.asp')},{t:'Earnings management',s:'HBR search',u:HBRS('earnings management')},{t:'CFA Program curriculum (FSA)',s:'CFA Institute',u:CFAI}]},

{id:'a12',track:'cfa1',topic:'ci',title:'Corporate issuers: governance, investment, capital structure',mins:40,blurb:'Stakeholders and governance, capital budgeting, cost of capital, capital structure and working capital.',
 lab:{key:'wacc',name:'WACC and capital-structure builder',intro:'Reused from MBA Core: relever beta and find the WACC-minimising mix.'},
 cards:[
  {h:'Business structures and stakeholders',b:`<p>Sole proprietorship, partnership, corporation (limited liability, separation of ownership and control). Stakeholders: shareholders, creditors, managers, employees, customers, suppliers, government. Principal–agent conflicts arise between them.</p>`},
  {h:'Governance mechanisms',b:`<p>Board independence and committees (audit, compensation, nomination), shareholder voting (proxy, cumulative voting), debt covenants, executive pay aligned to long-term value, ESG considerations and disclosure.</p>`},
  {h:'Capital investments',b:`<p>NPV is the primary rule; IRR can conflict with NPV for mutually exclusive projects (scale, timing). Real options (expand, abandon, delay) add value. Avoid sunk costs; include opportunity costs and externalities (cannibalisation).</p>`},
  {h:'Capital structure',b:`<p>MM without taxes: value independent of leverage. With taxes: debt adds value via the tax shield, offset by financial distress costs (static trade-off). Pecking order: internal funds → debt → equity, because of information asymmetry.</p>`},
  {h:'Working capital and liquidity',b:`<p>Cash conversion cycle, primary and secondary sources of liquidity, trade credit cost: cost of forgoing a 2/10 net 30 discount = (1 + 2/98)^(365/20) − 1 ≈ 44.6%.</p>`}],
 quiz:[
  {q:'For mutually exclusive projects where NPV and IRR conflict, choose by:',o:['Highest IRR','Highest NPV','Shortest payback'],a:1,w:'NPV measures value.'},
  {q:'A sunk cost should be:',o:['Included in project cash flows','Ignored','Depreciated'],a:1,w:'Irrelevant to the decision.'},
  {q:'MM with corporate taxes implies firm value:',o:['Is independent of leverage','Rises with debt due to the tax shield','Falls with debt'],a:1,w:'V_L = V_U + tD.'},
  {q:'Pecking order theory: firms prefer first:',o:['New equity','Internal funds','Debt'],a:1,w:'Then debt, then equity.'},
  {q:'Annual cost of forgoing 2/10 net 30 terms is closest to:',o:['2%','24%','45%'],a:2,w:'(1 + 2/98)^(365/20) − 1 ≈ 44.6%.'},
  {q:'An independent audit committee mainly addresses:',o:['Integrity of financial reporting','Marketing','Product pricing'],a:0,w:'Oversees reporting and auditors.'},
  {q:'Cumulative voting helps:',o:['Minority shareholders elect board representation','Management avoid votes','Creditors'],a:0,w:'Concentrates votes.'},
  {q:'A new product cannibalising existing sales: the lost sales should be:',o:['Ignored','Included as a cost','Counted as revenue'],a:1,w:'Incremental cash flows.'},
  {q:'Static trade-off theory balances:',o:['Tax shield benefits against financial distress costs','Dividends against buybacks','Debt against cash'],a:0,w:'Optimal leverage.'},
  {q:'A secondary source of liquidity is:',o:['Cash on hand','Renegotiating debt or selling assets','Short-term investments'],a:1,w:'Used when primary sources are insufficient.'}],
 srs:[{q:'MM with taxes?',a:'V_L = V_U + tD; offset by distress costs in trade-off theory.'},{q:'Pecking order?',a:'Internal funds → debt → equity.'},{q:'Cost of forgoing trade discount?',a:'(1 + d/(1 − d))^(365/(net − discount days)) − 1.'},{q:'NPV vs IRR conflict?',a:'Choose highest NPV.'}],
 read:[{t:'Modigliani–Miller theorem',s:'Wikipedia',u:WIKI('Modigliani%E2%80%93Miller_theorem')},{t:'G20/OECD Principles of Corporate Governance',s:'OECD',u:'https://www.oecd.org/en/publications/2023/09/g20-oecd-principles-of-corporate-governance-2023_60836fcb.html'},{t:'A Refresher on Net Present Value',s:'Harvard Business Review',u:'https://hbr.org/2014/11/a-refresher-on-net-present-value'}]},

{id:'a13',track:'cfa1',topic:'eq',title:'Equity markets, indices and efficiency',mins:40,blurb:'Market organisation, orders, margin, index construction and market efficiency.',
 lab:{key:'margin',name:'Margin and leverage calculator',intro:'Leverage, returns and the margin-call price.'},
 cards:[
  {h:'Market organisation',b:`<p>Primary vs secondary markets; quote-driven (dealers), order-driven (exchanges like Tadawul) and brokered markets. Orders: market, limit, stop; execution, validity and clearing instructions.</p>`},
  {h:'Margin',b:`<div class="formula">Leverage ratio = 1 ÷ initial margin · Margin call price = P₀(1 − IM) ÷ (1 − MM)</div>`},
  {h:'Index construction',b:`<p>Price-weighted (high-priced stocks dominate), equal-weighted (rebalancing, small-cap tilt), market-cap and float-adjusted (most common), fundamental weighting. Price return vs total return index.</p>`},
  {h:'Market efficiency',b:`<p>Weak form (past prices), semi-strong (all public information), strong (all information, including private). Anomalies: calendar effects, momentum, value — many fade once known or after costs.</p>`},
  {h:'Equity securities',b:`<p>Common vs preference shares; voting rights; callable and convertible preference; depository receipts; private vs public equity. Book value vs market value of equity; ROE as a key profitability measure.</p>`}],
 quiz:[
  {q:'Initial margin 40%, maintenance 25%, purchase price 50. Margin call price:',o:['40.00','37.50','33.33'],a:0,w:'50 × 0.6 ÷ 0.75.'},
  {q:'Initial margin 50% implies a leverage ratio of:',o:['1.5×','2×','0.5×'],a:1,w:'1 ÷ 0.5.'},
  {q:'In a price-weighted index, the biggest influence comes from:',o:['Largest companies by market cap','Highest-priced shares','Most liquid shares'],a:1,w:'Price weighting.'},
  {q:'If markets are semi-strong efficient, which cannot earn abnormal returns consistently?',o:['Technical analysis and fundamental analysis of public data','Insider trading','Neither'],a:0,w:'Public info is priced.'},
  {q:'A buy limit order:',o:['Executes at any price','Executes only at the limit price or lower','Executes at the stop price'],a:1,w:'Price protection.'},
  {q:'Float-adjusted market-cap weighting excludes:',o:['Shares not available to the public (e.g., strategic holdings)','All foreign shares','Dividends'],a:0,w:'Investable float.'},
  {q:'Equal-weighted indices tend to tilt toward:',o:['Large caps','Small caps','Bonds'],a:1,w:'Small stocks get the same weight as large.'},
  {q:'A stock that gives priority over common in dividends:',o:['Preference share','Depository receipt','Treasury share'],a:0,w:'Preferred.'},
  {q:'Buy at 50 on 40% margin, sell at 56, dividend 1, ignore interest. Return on equity:',o:['35%','14%','56%'],a:0,w:'(56 + 1 − 50) ÷ 20.'},
  {q:'Strong-form efficiency implies:',o:['Even insiders cannot earn abnormal returns','Only public info is priced','Prices follow trends'],a:0,w:'All information priced.'}],
 srs:[{q:'Margin call price?',a:'P₀(1 − IM) ÷ (1 − MM).'},{q:'Three forms of efficiency?',a:'Weak (prices), semi-strong (public info), strong (all info).'},{q:'Index weighting methods?',a:'Price, equal, market-cap (float-adjusted), fundamental.'},{q:'Leverage ratio?',a:'1 ÷ initial margin.'}],
 read:[{t:'Saudi Exchange (Tadawul)',s:'Saudi Exchange',u:'https://www.saudiexchange.sa/'},{t:'Efficient-market hypothesis',s:'Wikipedia',u:WIKI('Efficient-market_hypothesis')},{t:'Buying on margin',s:'Investopedia',u:INV('b/buyingonmargin.asp')}]},

{id:'a14',track:'cfa1',topic:'eq',title:'Industry analysis and equity valuation',mins:45,blurb:'Industry and company analysis, dividend discount models and multiples.',
 lab:{key:'ddm',name:'Two-stage DDM and justified P/E',intro:'Value a share with high growth then stable growth.'},
 cards:[
  {h:'Industry analysis',b:`<p>Classify (GICS-like sectors), assess life cycle (embryonic → growth → shakeout → mature → decline), competitive forces, and external influences (technology, demographics, government, social). Forecast company revenue from industry growth and share.</p>`},
  {h:'Dividend discount models',b:`<div class="formula">Gordon: V₀ = D₁ ÷ (r − g) · g = b × ROE (sustainable growth) · Multi-stage: discount explicit dividends + terminal value</div>`},
  {h:'Preferred stock',b:`<div class="formula">V = D ÷ r (non-callable, non-convertible perpetual preferred)</div>`},
  {h:'Multiples',b:`<p>P/E, P/B, P/S, P/CF, EV/EBITDA. Justified forward P/E = (D₁/E₁) ÷ (r − g). Use comparables (relative value) or fundamentals. EV/EBITDA is useful across different capital structures.</p>`},
  {h:'Intrinsic vs market value',b:`<p>If intrinsic value > market price, the share is undervalued — subject to model and input uncertainty. Use several methods and sensitivity ranges.</p>`}],
 quiz:[
  {q:'D₀ 2.00, g 4%, r 10%. Gordon value:',o:['33.33','34.67','20.80'],a:1,w:'2.08 ÷ 0.06.'},
  {q:'Retention ratio 60%, ROE 15%. Sustainable growth:',o:['9%','6%','15%'],a:0,w:'0.6 × 15%.'},
  {q:'Preferred paying 5 a year, required return 8%:',o:['62.50','40.00','5.40'],a:0,w:'5 ÷ 0.08.'},
  {q:'Payout 40%, r 10%, g 6%. Justified forward P/E:',o:['10×','6.7×','4×'],a:0,w:'0.4 ÷ 0.04.'},
  {q:'EV/EBITDA is preferred over P/E when comparing companies with:',o:['Different capital structures','Same leverage','No debt'],a:0,w:'Capital-structure neutral.'},
  {q:'The Gordon model requires:',o:['r > g','g > r','g = 0'],a:0,w:'Otherwise value is infinite or negative.'},
  {q:'An industry with consolidation and slowing growth is in:',o:['Embryonic stage','Shakeout stage','Decline stage'],a:1,w:'Shakeout follows growth.'},
  {q:'Intrinsic value 48, market price 40. The share appears:',o:['Overvalued','Undervalued','Fairly valued'],a:1,w:'Value > price.'},
  {q:'Raising required return, other things equal, makes DDM value:',o:['Rise','Fall','Unchanged'],a:1,w:'Higher discount rate.'},
  {q:'P/B is especially useful for:',o:['Banks and asset-heavy firms','Early-stage software','Companies with negative book value'],a:0,w:'Book values meaningful.'}],
 srs:[{q:'Gordon growth model?',a:'V₀ = D₁ ÷ (r − g).'},{q:'Sustainable growth?',a:'g = retention × ROE.'},{q:'Justified forward P/E?',a:'Payout ÷ (r − g).'},{q:'Industry life cycle?',a:'Embryonic, growth, shakeout, mature, decline.'}],
 read:[{t:'Damodaran Online: valuation',s:'NYU Stern',u:DAMO},{t:'Dividend discount model',s:'Investopedia',u:INV('d/ddm.asp')},{t:'The Five Competitive Forces That Shape Strategy',s:'Harvard Business Review',u:'https://hbr.org/2008/01/the-five-competitive-forces-that-shape-strategy'}]},

{id:'a15',track:'cfa1',topic:'fi',title:'Fixed income: instruments, pricing and yields',mins:45,blurb:'Bond features, markets, pricing, yield measures and the yield curve.',
 lab:{key:'bond',name:'Bond price–yield calculator',intro:'Price a bond, see premium vs discount, and the convex price–yield curve.'},
 cards:[
  {h:'Bond features',b:`<p>Issuer, maturity, par, coupon, currency, seniority, covenants, collateral, embedded options (callable benefits the issuer; putable and convertible benefit the investor). Sukuk are Sharia-compliant certificates structured around assets.</p>`},
  {h:'Pricing',b:`<div class="formula">P = Σ CPN ÷ (1 + r)^t + Par ÷ (1 + r)^N</div><p>Coupon > YTM → premium; coupon < YTM → discount. Prices converge to par at maturity ("pull to par").</p>`},
  {h:'Yield measures',b:`<p>Current yield = coupon ÷ price; YTM (IRR of cash flows); yield to call / yield to worst; street vs true yield; bond-equivalent yield for semi-annual bonds. Full price = flat (clean) price + accrued interest.</p>`},
  {h:'Spot, forward and par curves',b:`<p>Spot rates discount single cash flows; forward rates are implied future rates; par curve gives coupon rates that price bonds at par. Spreads: G-spread (over government), I-spread (over swaps), Z-spread (constant over the spot curve), OAS (removes option value).</p>`},
  {h:'Floating-rate notes',b:`<p>Coupon = reference rate + quoted margin; priced near par when the required margin equals the quoted margin. Money-market instruments use discount or add-on yields.</p>`}],
 quiz:[
  {q:'Coupon 5%, YTM 6%. The bond trades at:',o:['A premium','A discount','Par'],a:1,w:'Coupon below required yield.'},
  {q:'A callable bond compared with an otherwise identical option-free bond has:',o:['Higher price','Lower price (higher yield)','Same price'],a:1,w:'Investor is short the call.'},
  {q:'Full price equals:',o:['Flat price − accrued interest','Flat price + accrued interest','Par + coupon'],a:1,w:'Dirty = clean + accrued.'},
  {q:'Annual 6% coupon, 3 years, YTM 6%. Price per 100:',o:['100.00','97.33','102.67'],a:0,w:'Coupon = yield.'},
  {q:'The spread that is constant over the whole government spot curve is the:',o:['G-spread','Z-spread','I-spread'],a:1,w:'Zero-volatility spread.'},
  {q:'OAS for a callable bond compared with its Z-spread is:',o:['Higher','Lower','Equal'],a:1,w:'OAS = Z-spread − option cost (for callables).'},
  {q:'Current yield on a bond priced at 95 with a 4.75 coupon:',o:['5.00%','4.75%','4.51%'],a:0,w:'4.75 ÷ 95.'},
  {q:'A putable bond benefits:',o:['The issuer','The investor','Neither'],a:1,w:'Investor can sell back.'},
  {q:'If the yield curve is upward sloping, forward rates are generally:',o:['Above spot rates','Below spot rates','Equal'],a:0,w:'Forwards exceed spots when curve rises.'},
  {q:'Sukuk are:',o:['Conventional bonds with Arabic documentation','Sharia-compliant certificates structured around underlying assets or ventures','Equity shares'],a:1,w:'Asset-linked returns rather than interest.'}],
 srs:[{q:'Premium vs discount?',a:'Coupon > YTM → premium; coupon < YTM → discount.'},{q:'Full price?',a:'Flat price + accrued interest.'},{q:'Z-spread vs OAS?',a:'Z: constant spread over spot curve; OAS removes embedded option value.'},{q:'Callable bond yield?',a:'Higher yield/lower price vs option-free (investor short call).'}],
 read:[{t:'Bond pricing and yields',s:'Investopedia',u:INV('y/yieldtomaturity.asp')},{t:'Sukuk',s:'Wikipedia',u:WIKI('Sukuk')},{t:'MIT 15.401 Finance Theory I',s:'MIT OpenCourseWare',u:OCW('finance theory')}]},

{id:'a16',track:'cfa1',topic:'fi',title:'Term structure, duration and convexity',mins:45,blurb:'Interest-rate risk: Macaulay and modified duration, convexity and yield-curve risk.',
 lab:{key:'duration',name:'Duration and convexity calculator',intro:'Estimate price changes and compare with the exact change.'},
 cards:[
  {h:'Duration family',b:`<ul><li><b>Macaulay:</b> weighted average time to cash flows.</li><li><b>Modified:</b> MacD ÷ (1 + y); % price change per 1% yield change.</li><li><b>Effective:</b> (P₋ − P₊) ÷ (2 × P₀ × Δy), used for bonds with embedded options.</li><li><b>Money duration / PVBP:</b> currency change per basis point.</li></ul>`},
  {h:'Convexity',b:`<div class="formula">%ΔP ≈ −ModDur × Δy + ½ × Convexity × (Δy)²</div><p>Positive convexity helps the holder: gains exceed losses for equal yield moves. Callable bonds show negative convexity at low yields.</p>`},
  {h:'What raises duration',b:`<p>Longer maturity, lower coupon, lower yield → higher duration. Zero-coupon bond: Macaulay duration = maturity.</p>`},
  {h:'Investment horizon',b:`<p>When the investment horizon equals Macaulay duration, coupon reinvestment risk and price risk roughly offset for a parallel shift (immunisation).</p>`},
  {h:'Yield-curve risk',b:`<p>Duration assumes parallel shifts. Key rate durations measure sensitivity to specific maturities (steepening, flattening, twists).</p>`}],
 quiz:[
  {q:'Modified duration 7, yields rise 50 bp. Approximate price change:',o:['−3.5%','−7%','+3.5%'],a:0,w:'−7 × 0.005.'},
  {q:'Macaulay duration of a 5-year zero-coupon bond:',o:['5','Less than 5','More than 5'],a:0,w:'Single cash flow at maturity.'},
  {q:'Which bond has the highest duration?',o:['10-year, 8% coupon','10-year, 2% coupon','5-year, 2% coupon'],a:1,w:'Long maturity, low coupon.'},
  {q:'MacD 4.5, yield 5% (annual). ModDur:',o:['4.29','4.73','4.50'],a:0,w:'4.5 ÷ 1.05.'},
  {q:'Effective duration is required for:',o:['Option-free bonds only','Bonds with embedded options','Zero-coupon bonds'],a:1,w:'Cash flows change with rates.'},
  {q:'Positive convexity means for equal yield moves up and down:',o:['Price gain exceeds price loss','Loss exceeds gain','They are equal'],a:0,w:'Curvature benefit.'},
  {q:'Callable bonds at low yields exhibit:',o:['Positive convexity','Negative convexity','Zero duration'],a:1,w:'Price capped near call price.'},
  {q:'ModDur 6, convexity 50, yields fall 100 bp. Estimated price change:',o:['+6.25%','+5.75%','+6.00%'],a:0,w:'6% + 0.5 × 50 × 0.0001 = 6.25%.'},
  {q:'Immunisation of a single liability matches the liability\'s horizon with the portfolio\'s:',o:['Maturity','Macaulay duration','Coupon'],a:1,w:'Offsets price and reinvestment risk.'},
  {q:'Key rate durations measure sensitivity to:',o:['Parallel shifts only','Changes at specific points on the curve','Credit spreads'],a:1,w:'Shape risk.'}],
 srs:[{q:'Approximate %ΔP?',a:'−ModDur × Δy + ½ Convexity × Δy².'},{q:'ModDur?',a:'MacDur ÷ (1 + y per period).'},{q:'Duration drivers?',a:'Longer maturity, lower coupon, lower yield → higher duration.'},{q:'Effective duration formula?',a:'(P₋ − P₊) ÷ (2P₀Δy).'}],
 read:[{t:'Bond duration',s:'Wikipedia',u:WIKI('Bond_duration')},{t:'Convexity (finance)',s:'Wikipedia',u:WIKI('Bond_convexity')},{t:'Duration',s:'Investopedia',u:INV('d/duration.asp')}]},

{id:'a17',track:'cfa1',topic:'fi',title:'Credit risk and securitisation',mins:40,blurb:'Default risk, ratings, spreads, and asset-backed securities.',
 lab:{key:'credit',name:'Expected loss and tranche waterfall',intro:'Compute expected loss and see how pool losses hit each tranche.'},
 cards:[
  {h:'Credit risk components',b:`<div class="formula">Expected loss = PD × LGD (× exposure) · LGD = 1 − recovery rate</div><p>Also spread risk, downgrade risk and market liquidity risk.</p>`},
  {h:'Ratings and seniority',b:`<p>Investment grade (BBB−/Baa3 and above) vs high yield. Priority of claims: secured debt before unsecured, senior before subordinated. Notching: issue ratings can differ from issuer ratings.</p>`},
  {h:'Credit analysis',b:`<p>The four Cs plus industry, leverage (debt/EBITDA), coverage, and cash-flow measures. Sovereign analysis adds institutional, economic, fiscal, monetary and external factors.</p>`},
  {h:'Securitisation',b:`<p>A special purpose entity buys assets (mortgages, auto loans, receivables) and issues tranches. Credit enhancement: subordination (waterfall), overcollateralisation, reserve accounts, excess spread. Benefits: funding diversification, risk transfer.</p>`},
  {h:'Mortgage-backed securities',b:`<p>Prepayment risk: contraction risk when rates fall, extension risk when rates rise. CMOs redistribute prepayment risk across tranches (sequential pay, PAC/support).</p>`}],
 quiz:[
  {q:'PD 2%, recovery 40%. Expected loss as % of exposure:',o:['1.2%','0.8%','2.0%'],a:0,w:'2% × 60%.'},
  {q:'The lowest investment-grade rating (S&P scale) is:',o:['BBB−','BB+','A−'],a:0,w:'Below is high yield.'},
  {q:'In a securitisation waterfall, losses first hit the:',o:['Senior tranche','Equity (first-loss) tranche','All tranches equally'],a:1,w:'Subordination.'},
  {q:'Pool loss 18%, equity tranche 10%, mezzanine 20%. Mezzanine tranche loses:',o:['8% of the pool (40% of the tranche)','18%','None'],a:0,w:'Equity absorbs 10, mezz absorbs 8 of 20.'},
  {q:'When rates fall, MBS holders face:',o:['Extension risk','Contraction (prepayment) risk','No risk'],a:1,w:'Borrowers refinance.'},
  {q:'Overcollateralisation means:',o:['Collateral value exceeds the securities issued','Insurance from a third party','A cash reserve'],a:0,w:'Internal credit enhancement.'},
  {q:'Approximate credit spread ≈',o:['PD × LGD','PD + LGD','Recovery rate'],a:0,w:'Compensation for expected loss (plus premia).'},
  {q:'Secured debt ranks:',o:['Below unsubordinated unsecured','Above unsecured in the priority of claims','Equal to equity'],a:1,w:'Claim on collateral.'},
  {q:'A key benefit of securitisation to banks is:',o:['Higher leverage on the same assets','Funding and risk transfer, freeing capital','Avoiding all regulation'],a:1,w:'Originate-to-distribute.'},
  {q:'Downgrade risk refers to:',o:['Loss from a rating cut and wider spreads','Default with zero recovery','Prepayment'],a:0,w:'Credit migration.'}],
 srs:[{q:'Expected loss?',a:'PD × LGD × exposure; LGD = 1 − recovery.'},{q:'Credit enhancements?',a:'Subordination, overcollateralisation, reserve accounts, excess spread (external: guarantees).'},{q:'MBS prepayment risks?',a:'Contraction (rates fall), extension (rates rise).'},{q:'IG cut-off?',a:'BBB−/Baa3.'}],
 read:[{t:'Expected loss',s:'Wikipedia',u:WIKI('Expected_loss')},{t:'Securitization',s:'Wikipedia',u:WIKI('Securitization')},{t:'Credit ratings',s:'Investopedia',u:INV('c/creditrating.asp')}]},

{id:'a18',track:'cfa1',topic:'der',title:'Derivatives: forwards, futures, swaps and options',mins:45,blurb:'Instruments, no-arbitrage pricing, put–call parity and the binomial model.',
 lab:{key:'options',name:'Option payoffs and one-period binomial',intro:'Payoff diagrams, risk-neutral valuation and parity.'},
 cards:[
  {h:'Instruments',b:`<p>Forward commitments (forwards, futures, swaps) vs contingent claims (options, credit derivatives). Futures are standardised, exchange-traded and marked to market daily; forwards are OTC with counterparty risk.</p>`},
  {h:'No-arbitrage pricing',b:`<div class="formula">F₀ = S₀(1 + r)^T (no income or costs) · adjust for income (−) and storage costs (+)</div><p>The value of a forward at inception is zero; later it depends on the change in forward price.</p>`},
  {h:'Options',b:`<p>Call payoff max(0, S_T − K); put payoff max(0, K − S_T). Moneyness, intrinsic and time value. Factors: S, K, volatility, time, rates, income.</p>`},
  {h:'Put–call parity',b:`<div class="formula">S₀ + p₀ = c₀ + PV(K) · Put–call–forward parity: F₀/(1 + r)^T + p₀ = c₀ + PV(K)</div>`},
  {h:'Binomial model',b:`<div class="formula">q = (1 + r − d) ÷ (u − d) · c₀ = [q·c_u + (1 − q)·c_d] ÷ (1 + r)</div><p>Risk-neutral probability, not real-world probability.</p>`}],
 quiz:[
  {q:'Futures differ from forwards mainly in being:',o:['OTC and customised','Exchange-traded, standardised and marked to market','Free of margin'],a:1,w:'Clearing house.'},
  {q:'S₀ 100, r 5% for 1 year, no income. Forward price:',o:['105','100','95.24'],a:0,w:'100 × 1.05.'},
  {q:'The value of a forward contract at initiation is:',o:['The forward price','Zero','The spot price'],a:1,w:'Priced so no value changes hands.'},
  {q:'Put–call parity: S + p =',o:['c + PV(K)','c − PV(K)','K + c'],a:0,w:'Fiduciary call = protective put.'},
  {q:'u 1.2, d 0.8, r 5%. Risk-neutral up probability:',o:['0.625','0.500','0.600'],a:0,w:'(1.05 − 0.8) ÷ 0.4.'},
  {q:'S 100, K 100, u 1.2, d 0.8, r 5%. One-period call value:',o:['11.90','12.50','10.00'],a:0,w:'0.625 × 20 ÷ 1.05.'},
  {q:'Higher volatility makes both calls and puts:',o:['Less valuable','More valuable','Unaffected'],a:1,w:'More upside optionality.'},
  {q:'A swap can be viewed as a series of:',o:['Options','Forward contracts','Bonds only'],a:1,w:'Off-market forwards.'},
  {q:'A call with S < K is:',o:['In the money','Out of the money','At the money'],a:1,w:'No intrinsic value.'},
  {q:'Long put payoff at expiry with K 100 and S_T 80:',o:['20','0','80'],a:0,w:'max(0, 100 − 80).'}],
 srs:[{q:'Forward price (no income)?',a:'F₀ = S₀(1 + r)^T.'},{q:'Put–call parity?',a:'S + p = c + PV(K).'},{q:'Risk-neutral probability?',a:'q = (1 + r − d) ÷ (u − d).'},{q:'Forward commitments vs contingent claims?',a:'Forwards/futures/swaps vs options/credit derivatives.'}],
 read:[{t:'Put–call parity',s:'Investopedia',u:INV('p/putcallparity.asp')},{t:'Binomial options pricing model',s:'Wikipedia',u:WIKI('Binomial_options_pricing_model')},{t:'Futures contract',s:'Wikipedia',u:WIKI('Futures_contract')}]},

{id:'a19',track:'cfa1',topic:'alt',title:'Alternative investments',mins:40,blurb:'Private capital, real estate, infrastructure, natural resources, hedge funds and digital assets.',
 lab:{key:'altfees',name:'Hedge-fund fees and cap-rate valuation',intro:'Net returns after "2 and 20", and property value from NOI.'},
 cards:[
  {h:'Features and methods',b:`<p>Alternatives offer diversification and return potential but bring illiquidity, leverage, opacity, high fees and difficult performance measurement. Access: direct, co-investment, fund investing.</p>`},
  {h:'Fees and structures',b:`<p>Limited partnerships with management fees (on committed or invested capital) and incentive fees (carried interest) above a hurdle, with high-water marks and clawbacks. Waterfalls can be whole-of-fund (European) or deal-by-deal (American).</p>`},
  {h:'Private capital and real estate',b:`<p>Private equity (LBO, venture, growth), private debt (direct lending, mezzanine, distressed). Real estate valuation: income approach (NOI ÷ cap rate), cost approach, sales comparison. REITs offer liquid exposure.</p>`},
  {h:'Infrastructure and natural resources',b:`<p>Infrastructure: long-lived, often regulated, stable cash flows (brownfield vs greenfield). Natural resources: commodities, farmland, timberland. Commodity futures returns = spot + roll + collateral yield.</p>`},
  {h:'Hedge funds and digital assets',b:`<p>Strategies: equity long/short, event-driven, relative value, macro. Digital assets: cryptocurrencies, tokens and stablecoins built on distributed ledgers; high volatility and evolving regulation.</p>`}],
 quiz:[
  {q:'Fund starts at 100m, gross return 15%, 2% management fee on start assets, 20% incentive above high-water mark of 100m, incentive net of management fee. Net return:',o:['10.40%','12.00%','11.00%'],a:0,w:'115 − 2 = 113; incentive 20% × 13 = 2.6; 110.4 → 10.4%.'},
  {q:'NOI 12m, cap rate 7.5%. Property value:',o:['160m','90m','120m'],a:0,w:'12 ÷ 0.075.'},
  {q:'A high-water mark ensures incentive fees are paid only:',o:['On gains above the previous peak value','On all gains','After 5 years'],a:0,w:'No fees on recouping losses.'},
  {q:'A European (whole-of-fund) waterfall pays carry:',o:['Deal by deal','After LPs receive their capital and hurdle across the fund','Never'],a:1,w:'More LP-friendly.'},
  {q:'Commodity futures total return components:',o:['Spot, roll and collateral returns','Dividends and coupons','Only spot changes'],a:0,w:'Three parts.'},
  {q:'Brownfield infrastructure refers to:',o:['New projects to be built','Existing operating assets','Contaminated land only'],a:1,w:'Lower construction risk.'},
  {q:'Which is NOT a typical feature of alternatives?',o:['Illiquidity','High transparency and daily pricing','Higher fees'],a:1,w:'Usually opaque and infrequently priced.'},
  {q:'An equity long/short fund mainly seeks to:',o:['Profit from stock selection while reducing market exposure','Hold only bonds','Track an index'],a:0,w:'Alpha from longs and shorts.'},
  {q:'Appraisal-based real estate indices tend to:',o:['Overstate volatility','Understate volatility and correlation (smoothing)','Be identical to REIT indices'],a:1,w:'Infrequent appraisals smooth returns.'},
  {q:'Clawback provisions protect:',o:['The general partner','Limited partners if the GP was overpaid carry','Lenders'],a:1,w:'Return of excess carry.'}],
 srs:[{q:'Cap-rate valuation?',a:'Value = NOI ÷ cap rate.'},{q:'High-water mark?',a:'Incentive fee only on gains above prior peak NAV.'},{q:'Commodity futures return?',a:'Spot + roll + collateral yield.'},{q:'European vs American waterfall?',a:'Whole-of-fund (LP-friendly) vs deal-by-deal.'}],
 read:[{t:'CAIA Association',s:'CAIA',u:'https://caia.org/'},{t:'Capitalization rate',s:'Investopedia',u:INV('c/capitalizationrate.asp')},{t:'Hedge fund',s:'Wikipedia',u:WIKI('Hedge_fund')}]},

{id:'a20',track:'cfa1',topic:'pm',title:'Portfolio management and risk',mins:45,blurb:'Risk and return, diversification, CAPM, the IPS, behavioural biases and risk management.',
 lab:{key:'frontier',name:'Two-asset frontier and CAPM',intro:'See diversification bend the frontier; compute CAPM returns.'},
 cards:[
  {h:'Diversification',b:`<div class="formula">σ²_p = w₁²σ₁² + w₂²σ₂² + 2w₁w₂ρσ₁σ₂</div><p>Lower correlation → more risk reduction. Efficient frontier: highest return for each level of risk. With a risk-free asset, the capital allocation line touches the optimal risky portfolio.</p>`},
  {h:'CAPM and the SML',b:`<div class="formula">E(R) = R_f + β[E(R_m) − R_f] · β = Cov(R_i, R_m) ÷ σ²_m</div><p>Only systematic risk is priced. Performance: Sharpe (total risk), Treynor (beta), M², Jensen's alpha.</p>`},
  {h:'The investment policy statement',b:`<p>Return and risk objectives (ability and willingness to take risk) plus constraints: liquidity, time horizon, tax, legal and regulatory, unique circumstances. Then strategic asset allocation.</p>`},
  {h:'Behavioural finance',b:`<p>Cognitive errors (conservatism, confirmation, representativeness, illusion of control, hindsight, anchoring, mental accounting, framing, availability) vs emotional biases (loss aversion, overconfidence, self-control, status quo, endowment, regret aversion).</p>`},
  {h:'Risk management',b:`<p>Identify, measure, modify (avoid, accept, transfer, shift) and monitor risk within a risk budget. Measures: standard deviation, beta, duration, VaR, scenario and stress tests. Fintech and big data increasingly support it.</p>`}],
 quiz:[
  {q:'R_f 4%, β 1.3, E(R_m) 10%. CAPM required return:',o:['11.8%','13.0%','10.0%'],a:0,w:'4 + 1.3 × 6.'},
  {q:'Which risk is priced in CAPM?',o:['Total risk','Systematic risk','Unsystematic risk'],a:1,w:'Diversifiable risk earns no premium.'},
  {q:'Sharpe ratio uses:',o:['Beta','Total standard deviation','Tracking error'],a:1,w:'(R_p − R_f) ÷ σ_p.'},
  {q:'Correlation of +1 between two assets means diversification:',o:['Reduces risk the most','Gives no risk reduction','Eliminates all risk'],a:1,w:'Portfolio σ is a weighted average.'},
  {q:'A client\'s large liquidity need within a year mainly reduces:',o:['Willingness to take risk','Ability to take risk','Tax constraints'],a:1,w:'Capacity constraint.'},
  {q:'Loss aversion is a(n):',o:['Cognitive error','Emotional bias','Information-processing error'],a:1,w:'Emotional.'},
  {q:'Anchoring is a(n):',o:['Emotional bias','Cognitive error','Rational choice'],a:1,w:'Belief-perseverance/processing error.'},
  {q:'Treynor ratio divides excess return by:',o:['Standard deviation','Beta','VaR'],a:1,w:'Systematic risk.'},
  {q:'A stock plotting above the SML is:',o:['Overvalued','Undervalued (positive alpha)','Fairly priced'],a:1,w:'Expected return exceeds required.'},
  {q:'Buying insurance is an example of risk:',o:['Avoidance','Transfer','Acceptance'],a:1,w:'Shift to another party.'}],
 srs:[{q:'CAPM?',a:'E(R) = R_f + β(E(R_m) − R_f).'},{q:'Sharpe vs Treynor?',a:'Sharpe: excess return ÷ σ. Treynor: excess return ÷ β.'},{q:'IPS constraints?',a:'Liquidity, time horizon, tax, legal/regulatory, unique circumstances.'},{q:'Cognitive vs emotional bias examples?',a:'Cognitive: anchoring, confirmation. Emotional: loss aversion, overconfidence.'}],
 read:[{t:'Modern portfolio theory',s:'Wikipedia',u:WIKI('Modern_portfolio_theory')},{t:'Capital asset pricing model',s:'Investopedia',u:INV('c/capm.asp')},{t:'Behavioral finance',s:'Wikipedia',u:WIKI('Behavioral_economics')}]}
]);
